python3 - <<'EOF'
import json, sys

def make_line(depth):
    return '{"level":"ERROR","payload":' + "[" * depth + "]" * depth + "}"

def threshold():
    lo, hi = 1000, 1_000_000
    while lo < hi:
        mid = (lo + hi) // 2
        try:
            json.loads(make_line(mid))
            lo = mid + 1
        except RecursionError:
            hi = mid
    return lo

print("limit 1000, shallow stack:", threshold())

sys.setrecursionlimit(2000)
print("limit 2000, shallow stack:", threshold())
sys.setrecursionlimit(1000)

# measure at ~300 frames deep
def deep(frames_left):
    if frames_left:
        return deep(frames_left - 1)
    return threshold()
print("limit 1000, ~300 frames deep:", deep(300))
EOF

